export async function etsyFetch(db: Db, path: string, init: RequestInit = {}): Promise<unknown> {
  const { ETSY_API_KEY, ETSY_API_SECRET } = getSettings();

  // Mock mode: still rate-limit to preserve realistic timing (and let the
  // limiter's bookkeeping continue to track mock calls), but skip the network
  // entirely. The path passed to the mock dispatcher matches what the real
  // openapi.etsy.com URL would have used — fixtures match against /application/...
  if (isMockMode()) {
    return limiter.schedule(async () => {
      const method = (init.method ?? "GET").toUpperCase();
      return mockEtsyResponse(method, path, init.body ?? null);
    });
  }

  return limiter.schedule(() =>
    retry(
      async (bail) => {
        const token = await getValidAccessToken(db);
        const res = await fetch(`https://openapi.etsy.com/v3${path}`, {
          ...init,
          headers: {

    name: "create_draft_listing",
    match: ({ method, path }) =>
      method === "POST" &&
      /\/application\/shops\/[^/]+\/listings\/?$/.test(path),
    build: ({ body }) => {
      const title =
        typeof body === "object" &&
        body !== null &&
        "title" in body &&
        typeof (body as { title: unknown }).title === "string"
          ? (body as { title: string }).title
          : "Mock Listing";
      // Deterministic ID so a rerun produces the same etsy_listing_id and
      // resume guards in publisher.ts treat it as a real prior draft.
      const listingId = deterministicId(`listing:${title}`, 999_999_998) + 1;
      return {
        listing_id: listingId,
        user_id: 1,
        shop_id: 1,
        title,
        description: "Mock listing description",
        state: "draft",
        creation_timestamp: Math.floor(Date.now() / 1000),
        ending_timestamp: Math.floor(Date.now() / 1000) + 60 * 60 * 24 * 120,
        original_creation_timestamp: Math.floor(Date.now() / 1000),
        last_modified_timestamp: Math.floor(Date.now() / 1000),
        state_timestamp: Math.floor(Date.now() / 1000),
        quantity: 999,
